-- Add owner-scoped saved Agent configuration to the durable attachment-aware chat enqueue.
create or replace function public.moreai_enqueue_chat_run_with_config(
    p_user_id uuid,
    p_conversation_id uuid,
    p_content text,
    p_agent_key text,
    p_idempotency_key text,
    p_agent_config_id uuid,
    p_attachment_ids uuid[] default '{}'::uuid[]
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config'->>'id' is distinct from p_agent_config_id::text
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',jsonb_build_object(
                'id',v_config.id,'runtime_key',v_config.runtime_key,'name',v_config.name,
                'system_prompt',v_config.system_prompt,'tool_keys',to_jsonb(v_config.tool_keys),
                'version',v_config.version
            )
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$;
revoke all on function public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid,uuid[])
  from public, anon, authenticated;
grant execute on function public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid,uuid[])
  to service_role;

-- Safe retry of a saved Agent run reuses the exact owner-scoped configuration snapshot.
create or replace function public.moreai_enqueue_chat_run_with_config_snapshot(
    p_user_id uuid,
    p_source_run_id uuid,
    p_conversation_id uuid,
    p_content text,
    p_agent_key text,
    p_idempotency_key text,
    p_agent_config_snapshot jsonb,
    p_attachment_ids uuid[] default '{}'::uuid[]
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_source_run public.agent_runs%rowtype;
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
begin
    if p_user_id is null or p_source_run_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_snapshot is null or jsonb_typeof(p_agent_config_snapshot) <> 'object'
       or p_agent_config_snapshot->>'runtime_key' is distinct from p_agent_key
       or jsonb_typeof(p_agent_config_snapshot->'tool_keys') <> 'array'
       or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_saved_agent_retry_request' using errcode = '22023';
    end if;
    select * into v_source_run from public.agent_runs
     where id = p_source_run_id and user_id = p_user_id for share;
    if not found
       or v_source_run.status not in ('failed','timed_out','expired')
       or v_source_run.conversation_id is distinct from p_conversation_id
       or v_source_run.input->>'prompt' is distinct from p_content
       or v_source_run.input->>'agent_key' is distinct from p_agent_key
       or v_source_run.input->'agent_config' is distinct from p_agent_config_snapshot then
        raise exception 'saved_agent_retry_source_mismatch' using errcode = '42501';
    end if;
    if exists (
        select 1 from public.agent_run_events e
         where e.run_id = p_source_run_id
           and e.event_type like 'tool.%'
           and coalesce(e.payload->>'tool','') not in (
               'create_chat_completion','knowledge_search','google_search',
               'planning','workspace_read_file','terminate'
           )
    ) then
        raise exception 'saved_agent_retry_has_side_effects' using errcode = '22023';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0)
       or coalesce(v_source_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
        raise exception 'saved_agent_retry_attachment_mismatch' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from p_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',p_agent_config_snapshot,'retry_of_run_id',p_source_run_id
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$;
revoke all on function public.moreai_enqueue_chat_run_with_config_snapshot(uuid,uuid,uuid,text,text,text,jsonb,uuid[])
  from public, anon, authenticated;
grant execute on function public.moreai_enqueue_chat_run_with_config_snapshot(uuid,uuid,uuid,text,text,text,jsonb,uuid[])
  to service_role;

do $$
begin
  if not exists (
    select 1 from storage.buckets where id = 'moreai-artifacts'
  ) then
    raise exception 'required_private_artifact_bucket_missing';
  end if;
  update storage.buckets
     set public = false,
         file_size_limit = 150000000
   where id = 'moreai-artifacts';
end
$$;

-- First-party MoreAI EduTech domain. All writes are performed by the trusted API/worker.
create table if not exists public.learning_paths (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  created_by_run_id uuid not null references public.agent_runs(id) on delete restrict,
  title text not null check (length(btrim(title)) between 1 and 180),
  description text not null default '',
  education_level text not null default 'self_directed',
  learning_goal text not null default '',
  status text not null default 'draft' check (status in ('draft','active','completed','archived')),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists learning_paths_owner_updated_idx on public.learning_paths(owner_user_id, updated_at desc, id desc);

create table if not exists public.learning_modules (
  id uuid primary key default gen_random_uuid(),
  path_id uuid not null references public.learning_paths(id) on delete cascade,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  module_index integer not null check (module_index between 0 and 99),
  title text not null check (length(btrim(title)) between 1 and 180),
  summary text not null default '',
  estimated_minutes integer not null default 30 check (estimated_minutes between 1 and 10080),
  created_at timestamptz not null default now(),
  unique(path_id, module_index),
  unique(id, path_id, owner_user_id)
);
create index if not exists learning_modules_path_order_idx on public.learning_modules(path_id, module_index);

create table if not exists public.learning_lessons (
  id uuid primary key default gen_random_uuid(),
  path_id uuid not null references public.learning_paths(id) on delete cascade,
  module_id uuid not null,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  lesson_index integer not null check (lesson_index between 0 and 199),
  title text not null check (length(btrim(title)) between 1 and 180),
  content_md text not null default '',
  objectives jsonb not null default '[]'::jsonb check (jsonb_typeof(objectives) = 'array'),
  content_version integer not null default 1 check (content_version >= 1),
  status text not null default 'outline' check (status in ('outline','ready','archived')),
  source_run_id uuid references public.agent_runs(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (module_id, path_id, owner_user_id) references public.learning_modules(id, path_id, owner_user_id) on delete cascade,
  unique(module_id, lesson_index),
  unique(id, path_id, owner_user_id)
);
create index if not exists learning_lessons_module_order_idx on public.learning_lessons(module_id, lesson_index);

create table if not exists public.learning_lesson_versions (
  id uuid primary key default gen_random_uuid(),
  lesson_id uuid not null references public.learning_lessons(id) on delete cascade,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  version integer not null check (version >= 1),
  content_md text not null,
  objectives jsonb not null default '[]'::jsonb,
  source_run_id uuid references public.agent_runs(id) on delete set null,
  created_at timestamptz not null default now(),
  unique(lesson_id, version)
);

create table if not exists public.learning_enrollments (
  id uuid primary key default gen_random_uuid(),
  path_id uuid not null references public.learning_paths(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  status text not null default 'active' check (status in ('active','completed','paused','withdrawn')),
  enrolled_at timestamptz not null default now(),
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  unique(path_id, user_id)
);
create index if not exists learning_enrollments_user_idx on public.learning_enrollments(user_id, updated_at desc);

create table if not exists public.learning_quizzes (
  id uuid primary key default gen_random_uuid(),
  path_id uuid not null references public.learning_paths(id) on delete cascade,
  lesson_id uuid not null,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (length(btrim(title)) between 1 and 180),
  questions jsonb not null check (jsonb_typeof(questions) = 'array' and jsonb_array_length(questions) between 1 and 100),
  pass_score numeric(5,2) not null default 70 check (pass_score between 0 and 100),
  source_run_id uuid references public.agent_runs(id) on delete set null,
  created_at timestamptz not null default now(),
  foreign key (lesson_id, path_id, owner_user_id) references public.learning_lessons(id, path_id, owner_user_id) on delete cascade
);
create index if not exists learning_quizzes_lesson_idx on public.learning_quizzes(lesson_id, created_at desc);

create table if not exists public.learning_quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  quiz_id uuid not null references public.learning_quizzes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  run_id uuid not null references public.agent_runs(id) on delete restrict,
  answers jsonb not null check (jsonb_typeof(answers) = 'array'),
  score numeric(5,2) not null check (score between 0 and 100),
  passed boolean not null,
  feedback jsonb not null default '{}'::jsonb,
  submitted_at timestamptz not null default now(),
  unique(run_id, quiz_id)
);
create index if not exists learning_quiz_attempts_user_idx on public.learning_quiz_attempts(user_id, submitted_at desc);

create table if not exists public.learning_assessments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  path_id uuid not null references public.learning_paths(id) on delete cascade,
  module_id uuid references public.learning_modules(id) on delete set null,
  lesson_id uuid references public.learning_lessons(id) on delete set null,
  run_id uuid not null references public.agent_runs(id) on delete restrict,
  assessment_type text not null check (assessment_type in ('quiz','formative','project','rubric')),
  score numeric(5,2) check (score between 0 and 100),
  rubric jsonb not null default '[]'::jsonb,
  feedback jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists learning_assessments_user_idx on public.learning_assessments(user_id, created_at desc);

create table if not exists public.learning_progress (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  path_id uuid not null references public.learning_paths(id) on delete cascade,
  module_id uuid not null references public.learning_modules(id) on delete cascade,
  lesson_id uuid not null references public.learning_lessons(id) on delete cascade,
  status text not null default 'not_started' check (status in ('not_started','in_progress','completed')),
  progress_percent numeric(5,2) not null default 0 check (progress_percent between 0 and 100),
  last_run_id uuid references public.agent_runs(id) on delete set null,
  started_at timestamptz,
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  unique(user_id, lesson_id)
);
create index if not exists learning_progress_user_updated_idx on public.learning_progress(user_id, updated_at desc);

create table if not exists public.learning_run_artifacts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  run_id uuid not null references public.agent_runs(id) on delete cascade,
  artifact_type text not null check (artifact_type in ('learning_path','lesson','quiz','assessment','progress')),
  resource_id uuid not null,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique(run_id, artifact_type, resource_id)
);
create index if not exists learning_run_artifacts_user_idx on public.learning_run_artifacts(user_id, created_at desc);

do $$
declare t text;
begin
  foreach t in array array['learning_paths','learning_modules','learning_lessons','learning_lesson_versions','learning_enrollments','learning_quizzes','learning_quiz_attempts','learning_assessments','learning_progress','learning_run_artifacts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;

create or replace function public.moreai_learning_path_create(
  p_user_id uuid, p_run_id uuid, p_title text, p_description text,
  p_education_level text, p_learning_goal text, p_modules jsonb
) returns jsonb language plpgsql security invoker set search_path = ''
as $$
declare
  v_path public.learning_paths%rowtype;
  v_module jsonb;
  v_lesson jsonb;
  v_module_row public.learning_modules%rowtype;
  v_module_index integer := 0;
  v_lesson_index integer;
  v_count integer := 0;
begin
  if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
    raise exception 'learning_run_owner_mismatch' using errcode='42501';
  end if;
  if jsonb_typeof(p_modules) <> 'array' or jsonb_array_length(p_modules) not between 1 and 30 then
    raise exception 'learning_modules_invalid' using errcode='22023';
  end if;
  insert into public.learning_paths(owner_user_id,created_by_run_id,title,description,education_level,learning_goal,status)
  values(p_user_id,p_run_id,left(btrim(p_title),180),coalesce(p_description,''),coalesce(p_education_level,'self_directed'),coalesce(p_learning_goal,''),'active')
  returning * into v_path;
  for v_module in select value from jsonb_array_elements(p_modules) loop
    if length(btrim(coalesce(v_module->>'title',''))) = 0 then raise exception 'learning_module_title_required' using errcode='22023'; end if;
    insert into public.learning_modules(path_id,owner_user_id,module_index,title,summary,estimated_minutes)
    values(v_path.id,p_user_id,v_module_index,left(btrim(v_module->>'title'),180),coalesce(v_module->>'summary',''),greatest(1,least(10080,coalesce((v_module->>'estimated_minutes')::integer,30))))
    returning * into v_module_row;
    v_lesson_index := 0;
    if jsonb_typeof(v_module->'lessons') = 'array' then
      for v_lesson in select value from jsonb_array_elements(v_module->'lessons') loop
        insert into public.learning_lessons(path_id,module_id,owner_user_id,lesson_index,title,content_md,objectives,source_run_id,status)
        values(v_path.id,v_module_row.id,p_user_id,v_lesson_index,left(btrim(coalesce(v_lesson->>'title','Lesson')),180),coalesce(v_lesson->>'content_md',''),case when jsonb_typeof(v_lesson->'objectives')='array' then v_lesson->'objectives' else '[]'::jsonb end,p_run_id,case when coalesce(v_lesson->>'content_md','')='' then 'outline' else 'ready' end);
        v_lesson_index := v_lesson_index + 1; v_count := v_count + 1;
      end loop;
    end if;
    v_module_index := v_module_index + 1;
  end loop;
  insert into public.learning_enrollments(path_id,user_id,status) values(v_path.id,p_user_id,'active') on conflict(path_id,user_id) do nothing;
  insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
  values(p_user_id,p_run_id,'learning_path',v_path.id,jsonb_build_object('title',v_path.title,'module_count',v_module_index,'lesson_count',v_count));
  return jsonb_build_object('path_id',v_path.id,'title',v_path.title,'module_count',v_module_index,'lesson_count',v_count,'status',v_path.status);
end $$;

create or replace function public.moreai_learning_lesson_generate(
  p_user_id uuid,p_run_id uuid,p_lesson_id uuid,p_title text,p_content_md text,p_objectives jsonb
) returns jsonb language plpgsql security invoker set search_path = ''
as $$
declare v_lesson public.learning_lessons%rowtype; v_next integer;
begin
  if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then raise exception 'learning_run_owner_mismatch' using errcode='42501'; end if;
  select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id for update;
  if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;
